method intersection(interval1: (int, int), interval2: (int, int)) returns (result: string)
    requires interval1.0 <= interval1.1 // start of interval1 is less than or equal to end
    requires interval2.0 <= interval2.1 // start of interval2 is less than or equal to end
    ensures result == "YES" || result == "NO" // result is either "YES" or "NO"
    modifies {} // no state is modified
{
    // Compute the intersection of the two intervals
    var start := max(interval1.0, interval2.0);
    var end := min(interval1.1, interval2.1);

    if start > end {
        return "NO"; // Intervals do not intersect
    }

    var length := end - start + 1; // Length of intersection, inclusive

    // Check if length is a prime number
    if isPrime(length) {
        return "YES";
    } else {
        return "NO";
    }
}

method isPrime(n: int) returns (result: bool)
    requires n >= 0 // Non-negative integers only
    ensures result == (n > 1 && forall i: int :: 2 <= i < n ==> n % i != 0) // n is prime if greater than 1 and not divisible by any number from 2 to n-1
{
    if n <= 1 {
        return false;
    }
    var i := 2;
    while i * i <= n
        invariant 2 <= i <= n // i is within valid range
        invariant forall j: int :: 2 <= j < i ==> n % j != 0 // no divisors found so far
    {
        if n % i == 0 {
            return false; // Found a divisor
        }
        i := i + 1;
    }
    return true; // No divisors found, n is prime
}
